package e2e

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestRunBootstrap_BackendConfigReplacement(t *testing.T) {
	tmpDir := t.TempDir()

	// Create a test backend config
	backendConfig := `bucket = "tf-migrate-e2e-state"
key    = "v4/terraform.tfstate"
region = "auto"

endpoints = {
  s3 = "https://ACCOUNT_ID.r2.cloudflarestorage.com"
}

skip_credentials_validation = true
skip_region_validation      = true
skip_requesting_account_id  = true
skip_metadata_api_check     = true
skip_s3_checksum            = true
`

	backendFile := filepath.Join(tmpDir, "backend.hcl")
	err := os.WriteFile(backendFile, []byte(backendConfig), 0644)
	if err != nil {
		t.Fatalf("Failed to create backend config: %v", err)
	}

	// Read and replace ACCOUNT_ID
	content, err := os.ReadFile(backendFile)
	if err != nil {
		t.Fatalf("Failed to read backend config: %v", err)
	}

	testAccountID := "test-account-123"
	configured := strings.ReplaceAll(string(content), "ACCOUNT_ID", testAccountID)

	configuredFile := filepath.Join(tmpDir, "backend.configured.hcl")
	err = os.WriteFile(configuredFile, []byte(configured), 0644)
	if err != nil {
		t.Fatalf("Failed to write configured backend: %v", err)
	}

	// Verify the replacement worked
	configuredContent, err := os.ReadFile(configuredFile)
	if err != nil {
		t.Fatalf("Failed to read configured backend: %v", err)
	}

	configuredStr := string(configuredContent)

	if !strings.Contains(configuredStr, testAccountID) {
		t.Error("ACCOUNT_ID was not replaced in configured backend")
	}

	if strings.Contains(configuredStr, "ACCOUNT_ID") {
		t.Error("ACCOUNT_ID placeholder still present after replacement")
	}

	expectedEndpoint := "https://test-account-123.r2.cloudflarestorage.com"
	if !strings.Contains(configuredStr, expectedEndpoint) {
		t.Errorf("Expected endpoint %s not found in configured backend", expectedEndpoint)
	}
}

func TestRunBootstrap_StateFileValidation(t *testing.T) {
	tmpDir := t.TempDir()

	// Test checking for state file existence
	stateFile := filepath.Join(tmpDir, "terraform.tfstate")

	// State file doesn't exist
	if _, err := os.Stat(stateFile); os.IsNotExist(err) {
		// This is expected - bootstrap should fail if no state file
	} else {
		t.Error("State file should not exist initially")
	}

	// Create state file
	stateContent := `{
  "version": 4,
  "serial": 1,
  "resources": []
}`
	err := os.WriteFile(stateFile, []byte(stateContent), 0644)
	if err != nil {
		t.Fatalf("Failed to create state file: %v", err)
	}

	// Now state file should exist
	if _, err := os.Stat(stateFile); os.IsNotExist(err) {
		t.Error("State file should exist after creation")
	}
}

func TestRunBootstrap_EnvVarFormatting(t *testing.T) {
	// Test the environment variable formatting for terraform
	testVars := map[string]string{
		"AWS_ACCESS_KEY_ID":     "test-key-id",
		"AWS_SECRET_ACCESS_KEY": "test-secret-key",
	}

	// Verify these can be used in env format
	for k, v := range testVars {
		envLine := k + "=" + v
		parts := strings.Split(envLine, "=")

		if len(parts) != 2 {
			t.Errorf("Invalid env format: %s", envLine)
		}

		if parts[0] != k {
			t.Errorf("Key mismatch: got %s, want %s", parts[0], k)
		}

		if parts[1] != v {
			t.Errorf("Value mismatch: got %s, want %s", parts[1], v)
		}
	}
}

func TestRunBootstrap_BackendConfigFormat(t *testing.T) {
	// Test that backend config has correct HCL format
	backendConfig := `bucket = "tf-migrate-e2e-state"
key    = "v4/terraform.tfstate"
region = "auto"

endpoints = {
  s3 = "https://ACCOUNT_ID.r2.cloudflarestorage.com"
}

skip_credentials_validation = true
skip_region_validation      = true
skip_requesting_account_id  = true
skip_metadata_api_check     = true
skip_s3_checksum            = true
`

	// Verify it contains required fields
	requiredFields := []string{
		"bucket",
		"key",
		"region",
		"endpoints",
		"ACCOUNT_ID",
	}

	for _, field := range requiredFields {
		if !strings.Contains(backendConfig, field) {
			t.Errorf("Backend config missing required field: %s", field)
		}
	}
}

func TestRunBootstrap_R2EndpointFormat(t *testing.T) {
	// Test R2 endpoint URL format
	tests := []struct {
		accountID string
		want      string
	}{
		{
			accountID: "abc123",
			want:      "https://abc123.r2.cloudflarestorage.com",
		},
		{
			accountID: "test-account",
			want:      "https://test-account.r2.cloudflarestorage.com",
		},
	}

	for _, tt := range tests {
		t.Run(tt.accountID, func(t *testing.T) {
			endpoint := "https://" + tt.accountID + ".r2.cloudflarestorage.com"
			if endpoint != tt.want {
				t.Errorf("Endpoint = %s, want %s", endpoint, tt.want)
			}
		})
	}
}

func TestRunBootstrap_TerraformInitArgs(t *testing.T) {
	// Test terraform init arguments
	backendConfigFile := "backend.configured.hcl"

	initArgs := []string{"init", "-backend-config=" + backendConfigFile, "-migrate-state"}

	expectedArgs := []string{"init", "-backend-config=backend.configured.hcl", "-migrate-state"}

	if len(initArgs) != len(expectedArgs) {
		t.Errorf("Arg count mismatch: got %d, want %d", len(initArgs), len(expectedArgs))
	}

	for i, arg := range initArgs {
		if arg != expectedArgs[i] {
			t.Errorf("Arg %d: got %s, want %s", i, arg, expectedArgs[i])
		}
	}
}

func TestRunBootstrap_ConfigCleanup(t *testing.T) {
	tmpDir := t.TempDir()

	// Create a temp config file
	configFile := filepath.Join(tmpDir, "backend.configured.hcl")
	err := os.WriteFile(configFile, []byte("test content"), 0644)
	if err != nil {
		t.Fatalf("Failed to create config file: %v", err)
	}

	// Verify file exists
	if _, err := os.Stat(configFile); os.IsNotExist(err) {
		t.Error("Config file should exist")
	}

	// Simulate cleanup (defer os.Remove)
	os.Remove(configFile)

	// Verify file was removed
	if _, err := os.Stat(configFile); !os.IsNotExist(err) {
		t.Error("Config file should be removed")
	}
}

func TestRunBootstrap_StateBucketName(t *testing.T) {
	// Test that bucket name follows naming conventions
	bucketName := "tf-migrate-e2e-state"

	// Bucket name validation rules
	if len(bucketName) < 3 || len(bucketName) > 63 {
		t.Error("Bucket name length should be between 3 and 63 characters")
	}

	// Should only contain lowercase letters, numbers, and hyphens
	for _, c := range bucketName {
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-') {
			t.Errorf("Invalid character in bucket name: %c", c)
		}
	}

	// Should not start or end with hyphen
	if bucketName[0] == '-' || bucketName[len(bucketName)-1] == '-' {
		t.Error("Bucket name should not start or end with hyphen")
	}
}

func TestRunBootstrap_StateKey(t *testing.T) {
	// Test state key format
	stateKey := "v4/terraform.tfstate"

	if !strings.HasSuffix(stateKey, ".tfstate") {
		t.Error("State key should have .tfstate extension")
	}

	if !strings.HasPrefix(stateKey, "v4/") {
		t.Error("State key should be in v4/ directory")
	}
}

package authenticated_origin_pulls_certificate

import (
	"testing"

	"github.com/cloudflare/tf-migrate/internal/testhelpers"
)

func TestConfigTransformation_PerZone(t *testing.T) {
	migrator := NewV4ToV5Migrator()

	tests := []testhelpers.ConfigTestCase{
		{
			Name: "per-zone certificate with all fields",
			Input: `
resource "cloudflare_authenticated_origin_pulls_certificate" "test" {
  zone_id     = "abc123"
  certificate = "-----BEGIN CERTIFICATE-----\nMIIE...test\n-----END CERTIFICATE-----"
  private_key = "[REDACTED]"
  type        = "per-zone"
}`,
			Expected: `
resource "cloudflare_authenticated_origin_pulls_certificate" "test" {
  zone_id     = "abc123"
  certificate = "-----BEGIN CERTIFICATE-----\nMIIE...test\n-----END CERTIFICATE-----"
  private_key = "[REDACTED]"
}`,
		},
		{
			Name: "per-zone certificate with variable references",
			Input: `
resource "cloudflare_authenticated_origin_pulls_certificate" "test" {
  zone_id     = var.cloudflare_zone_id
  certificate = file("cert.pem")
  private_key = file("key.pem")
  type        = "per-zone"
}`,
			Expected: `
resource "cloudflare_authenticated_origin_pulls_certificate" "test" {
  zone_id     = var.cloudflare_zone_id
  certificate = file("cert.pem")
  private_key = file("key.pem")
}`,
		},
	}

	testhelpers.RunConfigTransformTests(t, tests, migrator)
}

func TestConfigTransformation_PerHostname(t *testing.T) {
	migrator := NewV4ToV5Migrator()

	tests := []testhelpers.ConfigTestCase{
		{
			Name: "per-hostname certificate with all fields",
			Input: `
resource "cloudflare_authenticated_origin_pulls_certificate" "test" {
  zone_id     = "abc123"
  certificate = "-----BEGIN CERTIFICATE-----\nMIIE...test\n-----END CERTIFICATE-----"
  private_key = "[REDACTED]"
  type        = "per-hostname"
}`,
			Expected: `
resource "cloudflare_authenticated_origin_pulls_hostname_certificate" "test" {
  zone_id     = "abc123"
  certificate = "-----BEGIN CERTIFICATE-----\nMIIE...test\n-----END CERTIFICATE-----"
  private_key = "[REDACTED]"
}

moved {
  from = cloudflare_authenticated_origin_pulls_certificate.test
  to   = cloudflare_authenticated_origin_pulls_hostname_certificate.test
}`,
		},
		{
			Name: "per-hostname certificate with variable references",
			Input: `
resource "cloudflare_authenticated_origin_pulls_certificate" "test" {
  zone_id     = var.cloudflare_zone_id
  certificate = file("hostname_cert.pem")
  private_key = file("hostname_key.pem")
  type        = "per-hostname"
}`,
			Expected: `
resource "cloudflare_authenticated_origin_pulls_hostname_certificate" "test" {
  zone_id     = var.cloudflare_zone_id
  certificate = file("hostname_cert.pem")
  private_key = file("hostname_key.pem")
}

moved {
  from = cloudflare_authenticated_origin_pulls_certificate.test
  to   = cloudflare_authenticated_origin_pulls_hostname_certificate.test
}`,
		},
	}

	testhelpers.RunConfigTransformTests(t, tests, migrator)
}

func TestConfigTransformation_Mixed(t *testing.T) {
	migrator := NewV4ToV5Migrator()

	tests := []testhelpers.ConfigTestCase{
		{
			Name: "both per-zone and per-hostname in same file",
			Input: `
resource "cloudflare_authenticated_origin_pulls_certificate" "per_zone" {
  zone_id     = "abc123"
  certificate = "-----BEGIN CERTIFICATE-----\nzone cert\n-----END CERTIFICATE-----"
  private_key = "[REDACTED]"
  type        = "per-zone"
}

resource "cloudflare_authenticated_origin_pulls_certificate" "per_hostname" {
  zone_id     = "abc123"
  certificate = "-----BEGIN CERTIFICATE-----\nhost cert\n-----END CERTIFICATE-----"
  private_key = "[REDACTED]"
  type        = "per-hostname"
}`,
			Expected: `
resource "cloudflare_authenticated_origin_pulls_certificate" "per_zone" {
  zone_id     = "abc123"
  certificate = "-----BEGIN CERTIFICATE-----\nzone cert\n-----END CERTIFICATE-----"
  private_key = "[REDACTED]"
}

resource "cloudflare_authenticated_origin_pulls_hostname_certificate" "per_hostname" {
  zone_id     = "abc123"
  certificate = "-----BEGIN CERTIFICATE-----\nhost cert\n-----END CERTIFICATE-----"
  private_key = "[REDACTED]"
}

moved {
  from = cloudflare_authenticated_origin_pulls_certificate.per_hostname
  to   = cloudflare_authenticated_origin_pulls_hostname_certificate.per_hostname
}`,
		},
	}

	testhelpers.RunConfigTransformTests(t, tests, migrator)
}

package authenticated_origin_pulls

import (
	"testing"

	"github.com/cloudflare/tf-migrate/internal/testhelpers"
)

func TestConfigTransformation(t *testing.T) {
	migrator := NewV4ToV5Migrator()

	testCases := []testhelpers.ConfigTestCase{
		{
			Name: "basic zone-wide AOP",
			Input: `
resource "cloudflare_authenticated_origin_pulls" "example" {
  zone_id = "0da42c8d2132a9ddaf714f9e7c920711"
  enabled = true
}`,
			Expected: `
resource "cloudflare_authenticated_origin_pulls_settings" "example" {
  zone_id = "0da42c8d2132a9ddaf714f9e7c920711"
  enabled = true
}
moved {
  from = cloudflare_authenticated_origin_pulls.example
  to   = cloudflare_authenticated_origin_pulls_settings.example
}`,
		},
		{
			Name: "zone-wide AOP disabled",
			Input: `
resource "cloudflare_authenticated_origin_pulls" "example" {
  zone_id = "0da42c8d2132a9ddaf714f9e7c920711"
  enabled = false
}`,
			Expected: `
resource "cloudflare_authenticated_origin_pulls_settings" "example" {
  zone_id = "0da42c8d2132a9ddaf714f9e7c920711"
  enabled = false
}
moved {
  from = cloudflare_authenticated_origin_pulls.example
  to   = cloudflare_authenticated_origin_pulls_settings.example
}`,
		},
		{
			Name: "Per-Hostname AOP (stays as authenticated_origin_pulls)",
			Input: `
resource "cloudflare_authenticated_origin_pulls" "example" {
  zone_id = "0da42c8d2132a9ddaf714f9e7c920711"
  hostname = "app.example.com"
  enabled = true
}`,
			Expected: `
resource "cloudflare_authenticated_origin_pulls" "example" {
  zone_id = "0da42c8d2132a9ddaf714f9e7c920711"
  config = [{
    hostname = "app.example.com"
    enabled  = true
  }]
}`,
		},
		{
			Name: "AOP with certificate (removed in v5)",
			Input: `
resource "cloudflare_authenticated_origin_pulls" "example" {
  zone_id = "0da42c8d2132a9ddaf714f9e7c920711"
  authenticated_origin_pulls_certificate = "cert-id-123"
  enabled = true
}`,
			Expected: `
resource "cloudflare_authenticated_origin_pulls_settings" "example" {
  zone_id = "0da42c8d2132a9ddaf714f9e7c920711"
  enabled = true
}
moved {
  from = cloudflare_authenticated_origin_pulls.example
  to   = cloudflare_authenticated_origin_pulls_settings.example
}`,
		},
		{
			Name: "Per-Hostname AOP with certificate (restructured to nested config)",
			Input: `
resource "cloudflare_authenticated_origin_pulls" "example" {
  zone_id = "0da42c8d2132a9ddaf714f9e7c920711"
  hostname = "app.example.com"
  authenticated_origin_pulls_certificate = "cert-id-123"
  enabled = true
}`,
			Expected: `
resource "cloudflare_authenticated_origin_pulls" "example" {
  zone_id = "0da42c8d2132a9ddaf714f9e7c920711"
  config = [{
    hostname = "app.example.com"
    cert_id  = "cert-id-123"
    enabled  = true
  }]
}`,
		},
		{
			Name: "multiple AOP resources",
			Input: `
resource "cloudflare_authenticated_origin_pulls" "example1" {
  zone_id = "zone-id-1"
  enabled = true
}

resource "cloudflare_authenticated_origin_pulls" "example2" {
  zone_id = "zone-id-2"
  enabled = false
}`,
			Expected: `
resource "cloudflare_authenticated_origin_pulls_settings" "example1" {
  zone_id = "zone-id-1"
  enabled = true
}
moved {
  from = cloudflare_authenticated_origin_pulls.example1
  to   = cloudflare_authenticated_origin_pulls_settings.example1
}

resource "cloudflare_authenticated_origin_pulls_settings" "example2" {
  zone_id = "zone-id-2"
  enabled = false
}
moved {
  from = cloudflare_authenticated_origin_pulls.example2
  to   = cloudflare_authenticated_origin_pulls_settings.example2
}`,
		},
		{
			Name: "AOP with depends_on",
			Input: `
resource "cloudflare_authenticated_origin_pulls" "example" {
  zone_id = "0da42c8d2132a9ddaf714f9e7c920711"
  enabled = true

  depends_on = [cloudflare_zone.example]
}`,
			Expected: `
resource "cloudflare_authenticated_origin_pulls_settings" "example" {
  zone_id = "0da42c8d2132a9ddaf714f9e7c920711"
  enabled = true

  depends_on = [cloudflare_zone.example]
}
moved {
  from = cloudflare_authenticated_origin_pulls.example
  to   = cloudflare_authenticated_origin_pulls_settings.example
}`,
		},
		{
			Name: "AOP with lifecycle",
			Input: `
resource "cloudflare_authenticated_origin_pulls" "example" {
  zone_id = "0da42c8d2132a9ddaf714f9e7c920711"
  enabled = true

  lifecycle {
    prevent_destroy = true
  }
}`,
			Expected: `
resource "cloudflare_authenticated_origin_pulls_settings" "example" {
  zone_id = "0da42c8d2132a9ddaf714f9e7c920711"
  enabled = true

  lifecycle {
    prevent_destroy = true
  }
}
moved {
  from = cloudflare_authenticated_origin_pulls.example
  to   = cloudflare_authenticated_origin_pulls_settings.example
}`,
		},
	}

	testhelpers.RunConfigTransformTests(t, testCases, migrator)
}

func TestCanHandle(t *testing.T) {
	migrator := NewV4ToV5Migrator()

	if !migrator.CanHandle("cloudflare_authenticated_origin_pulls") {
		t.Error("Expected migrator to handle cloudflare_authenticated_origin_pulls")
	}

	if migrator.CanHandle("cloudflare_some_other_resource") {
		t.Error("Expected migrator to not handle cloudflare_some_other_resource")
	}
}

# API Token Migration Guide (v4 → v5)

This guide explains how `cloudflare_api_token` resources migrate from v4 to v5.

## Quick Reference

| v4 Field | v5 Field | Change Type |
|----------|----------|-------------|
| `policy` (block) | `policies` (array) | Renamed + syntax change |
| `permission_groups` (list of strings) | `permission_groups` (list of objects) | Type change |
| `resources` (map) | `resources` (JSON string) | Type change + jsonencode |
| `effect` (optional) | `effect` (required, defaults to "allow") | Required field |
| `condition` (block) | `condition` (object) | Syntax change |
| - | `last_used_on` | Added (computed) |


---

## Migration Examples

### Example 1: Basic Single Policy Token

**v4 Configuration:**
```hcl
resource "cloudflare_api_token" "basic" {
  name = "terraform-token"

  policy {
    effect = "allow"
    permission_groups = ["c8fed203ed3043cba015a93ad1616f1f"]
    resources = {
      "com.cloudflare.api.account.*" = "*"
    }
  }
}
```

**v5 Configuration (After Migration):**
```hcl
resource "cloudflare_api_token" "basic" {
  name = "terraform-token"

  policies = [{
    effect = "allow"
    permission_groups = [{
      id = "c8fed203ed3043cba015a93ad1616f1f"
    }]
    resources = jsonencode({
      "com.cloudflare.api.account.*" = "*"
    })
  }]
}
```

**What Changed:**
- `policy` block → `policies` array attribute
- `permission_groups` strings → objects with `id` field
- `resources` map → `jsonencode()` wrapped JSON string

---

### Example 2: Multiple Policies with IP Conditions

**v4 Configuration:**
```hcl
resource "cloudflare_api_token" "restricted" {
  name = "multi-policy-token"

  policy {
    effect = "allow"
    permission_groups = ["c8fed203ed3043cba015a93ad1616f1f"]
    resources = {
      "com.cloudflare.api.account.*" = "*"
    }
  }

  policy {
    effect = "deny"
    permission_groups = ["82e64a83756745bbbb1c9c2701bf816b"]
    resources = {
      "com.cloudflare.api.account.billing.*" = "*"
    }
  }

  condition {
    request_ip {
      in     = ["192.168.1.0/24"]
      not_in = ["192.168.1.100/32"]
    }
  }
}
```

**v5 Configuration (After Migration):**
```hcl
resource "cloudflare_api_token" "restricted" {
  name = "multi-policy-token"

  policies = [{
    effect = "allow"
    permission_groups = [{
      id = "c8fed203ed3043cba015a93ad1616f1f"
    }]
    resources = jsonencode({
      "com.cloudflare.api.account.*" = "*"
    })
  }, {
    effect = "deny"
    permission_groups = [{
      id = "82e64a83756745bbbb1c9c2701bf816b"
    }]
    resources = jsonencode({
      "com.cloudflare.api.account.billing.*" = "*"
    })
  }]

  condition = {
    request_ip = {
      in     = ["192.168.1.0/24"]
      not_in = ["192.168.1.100/32"]
    }
  }
}
```

**What Changed:**
- Multiple `policy` blocks → Array of policy objects in `policies`
- Nested `condition` block → Object attribute
- Nested `request_ip` block → Object within condition

---

### Example 3: Policy Without Explicit Effect (Auto-defaults)

**v4 Configuration:**
```hcl
resource "cloudflare_api_token" "implicit" {
  name = "api-token-read"

  policy {
    # No effect specified
    permission_groups = ["e086da7e2179491d91ee5f35b3ca210a"]
    resources = {
      "com.cloudflare.api.account.*" = "*"
    }
  }
}
```

**v5 Configuration (After Migration):**
```hcl
resource "cloudflare_api_token" "implicit" {
  name = "api-token-read"

  policies = [{
    effect = "allow"  # ← Auto-added default
    permission_groups = [{
      id = "e086da7e2179491d91ee5f35b3ca210a"
    }]
    resources = jsonencode({
      "com.cloudflare.api.account.*" = "*"
    })
  }]
}
```

**What Changed:**
- Missing `effect` field defaults to `"allow"`
- All other transformations applied

---

### Example 4: Token with Dynamic References

**v4 Configuration:**
```hcl
variable "user_id" {
  default = "12345"
}

resource "cloudflare_api_token" "dynamic" {
  name = "user-specific-token"

  policy {
    permission_groups = ["c8fed203ed3043cba015a93ad1616f1f"]
    resources = {
      "com.cloudflare.api.user.${var.user_id}" = "*"
    }
  }
}
```

**v5 Configuration (After Migration):**
```hcl
variable "user_id" {
  default = "12345"
}

resource "cloudflare_api_token" "dynamic" {
  name = "user-specific-token"

  policies = [{
    effect = "allow"
    permission_groups = [{
      id = "c8fed203ed3043cba015a93ad1616f1f"
    }]
    resources = jsonencode({
      "com.cloudflare.api.user.${var.user_id}" = "*"
    })
  }]
}
```

**What Changed:**
- String interpolations preserved in `jsonencode()`
